        ('hautpflege', 'obf-3660005338682', 'Le shampooing douche concentré au monoï', 'Yves Rocher - 100 ml', 'Produktangaben aus dem Open-Beauty-Facts-Eintrag zu Le shampooing douche concentré au monoï, 100 ml.', 1999, 'https://images.openbeautyfacts.org/images/products/366/000/533/8682/front_fr.3.400.jpg', 'Le shampooing douche concentré au monoï, 100 ml', 17, 'OBF-3660005338682', '3660005338682', 'Yves Rocher'),
        ('hautpflege', 'obf-3181730142042', 'Dermo Hypo-allergenic', 'Sanex - 250 ml', 'Produktangaben aus dem Open-Beauty-Facts-Eintrag zu Dermo Hypo-allergenic, 250 ml.', 956, 'https://images.openbeautyfacts.org/images/products/318/173/014/2042/front_fr.5.400.jpg', 'Dermo Hypo-allergenic, 250 ml', 23, 'OBF-3181730142042', '3181730142042', 'Sanex'),
        ('hautpflege', 'obf-3600523434534', 'Hydra Sensitive Gel douche sève de Bouleau (format XL)', 'L''Oréal Paris - 300 ml', 'Produktangaben aus dem Open-Beauty-Facts-Eintrag zu Hydra Sensitive Gel douche sève de Bouleau (format XL), 300 ml.', 1584, 'https://images.openbeautyfacts.org/images/products/360/052/343/4534/front_fr.5.400.jpg', 'Hydra Sensitive Gel douche sève de Bouleau (format XL), 300 ml', 21, 'OBF-3600523434534', '3600523434534', 'L''Oréal Paris')
), upserted AS (
    INSERT INTO products (category_id, slug, name, short_description, description, price_cents, image_url, image_alt, inventory, featured, status, sku, barcode, manufacturer)
    SELECT categories.id, curated.slug, curated.name, curated.short_description,
        curated.description || E'\n\nCommunity product data: Open Beauty Facts (ODbL 1.0); product image: CC BY-SA 3.0. Verify this community-submitted record before sale. Price and inventory are synthetic local demo values.\nSource: https://world.openbeautyfacts.org/product/' || curated.barcode,
        curated.price_cents, curated.image_url, curated.image_alt, curated.inventory, FALSE, 'active', curated.sku, curated.barcode, curated.manufacturer
    FROM curated JOIN categories ON categories.slug = curated.category_slug
    ON CONFLICT (slug) DO UPDATE SET category_id = EXCLUDED.category_id, name = EXCLUDED.name,
        short_description = EXCLUDED.short_description, description = EXCLUDED.description,
        price_cents = EXCLUDED.price_cents, image_url = EXCLUDED.image_url, image_alt = EXCLUDED.image_alt,
        status = EXCLUDED.status, sku = EXCLUDED.sku, barcode = EXCLUDED.barcode, manufacturer = EXCLUDED.manufacturer, updated_at = NOW()
    RETURNING id, inventory
), opening_balance AS (
    INSERT INTO product_inventory_movements (product_id, movement_type, quantity_delta, inventory_before, inventory_after, reason, reference, actor_email)
    SELECT id, 'opening_balance', inventory, 0, inventory, 'Expanded curated local demo catalog opening balance', 'Open Beauty Facts demo seed', 'system:mitte-demo-seed'
    FROM upserted WHERE inventory > 0 AND NOT EXISTS (
        SELECT 1 FROM product_inventory_movements movement WHERE movement.product_id = upserted.id
            AND movement.movement_type = 'opening_balance' AND movement.reason = 'Expanded curated local demo catalog opening balance'
    ) RETURNING product_id
)
SELECT COUNT(*)::integer FROM upserted;
